import numpy as np
from scipy.optimize import minimize

name = "minimize(fun, [2.1], jac=jac, hess=hess, method='trust-exact', tol=1e-8, options={'initial_trust_radius': 10, 'maxiter': 10}) with fun(x)=x[0]-np.log(x[0]) if x[0]>0 else np.nan; jac(x)=np.array([1-1/x[0]]); hess(x)=np.array([[1/x[0]**2]]) if x[0]>0 else raise ValueError('Hessian evaluated outside domain')"


def fun(x):
    if x[0] > 0:
        return x[0] - np.log(x[0])
    return np.nan


def jac(x):
    return np.array([1 - 1 / x[0]])


def hess(x):
    if x[0] > 0:
        return np.array([[1 / x[0] ** 2]])
    raise ValueError('Hessian evaluated outside domain')

try:
    res = minimize(
        fun,
        [2.1],
        jac=jac,
        hess=hess,
        method='trust-exact',
        tol=1e-8,
        options={'initial_trust_radius': 10, 'maxiter': 10},
    )
    probe(name, res.x)
except Exception as e:
    probe_exception(name, e)

